python3 -c "
import json
with open('/app/resources/treasury_bulletin_1991_09.json') as f:
    data = json.load(f)

# Search for saving-related content
def find_saving(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if 'saving' in k.lower():
                print(f'{path}.{k}: {v}')
            find_saving(v, f'{path}.{k}')
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            find_saving(item, f'{path}[{i}]')

find_saving(data)
